        int n = grid.size();
        List<Integer> result = new ArrayList<>();
        PriorityQueue<Path> pq = new PriorityQueue<>(Comparator.comparing(p -> p.path));

        // Initialize the priority queue with all possible starting points
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                List<Integer> initialPath = new ArrayList<>();
                initialPath.add(grid.get(i).get(j));
                pq.offer(new Path(i, j, initialPath));
            }
        }

        // Directions for moving up, down, left, right
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.isEmpty()) {
            Path current = pq.poll();

            // If the path length is k, return it as the result
            if (current.path.size() == k) {
                return current.path;
            }

            // Explore neighbors
            for (int[] dir : directions) {
                int newX = current.x + dir[0];
                int newY = current.y + dir[1];

                if (newX >= 0 && newX < n && newY >= 0 && newY < n) {
                    List<Integer> newPath = new ArrayList<>(current.path);
                    newPath.add(grid.get(newX).get(newY));
                    pq.offer(new Path(newX, newY, newPath));
                }
            }
        }

        return result; // This line should never be reached due to problem constraints
    }

    private static class Path {
        int x, y;
        List<Integer> path;

        Path(int x, int y, List<Integer> path) {
            this.x = x;
            this.y = y;
            this.path = path;
        }
    }
}
